1	import { useState } from "react";
2	import { ChevronDown, ChevronUp } from "lucide-react";
3	import { Card, CardContent, CardHeader } from "@/components/ui/card";
4	import { Badge } from "@/components/ui/badge";
5	import type { Result } from "@/pages/Index";
6	
7	interface SkillsDetailPanelProps {
8	  result: Result;
9	}
10	
11	type SkillLevel = "Expert" | "Adv" | "Good" | "Mid" | "Low" | "Gap";
12	
13	const getSkillLevel = (score: number): SkillLevel => {
14	  if (score >= 90) return "Expert";
15	  if (score >= 70) return "Adv";
16	  if (score >= 55) return "Good";
17	  if (score >= 40) return "Mid";
18	  if (score >= 20) return "Low";
19	  return "Gap";
20	};
21	
22	const levelChipCls: Record<SkillLevel, string> = {
23	  Expert: "bg-emerald-500/10 text-emerald-600 border-emerald-500/20 dark:text-emerald-400",
24	  Adv: "bg-blue-500/10 text-blue-600 border-blue-500/20 dark:text-blue-400",
25	  Good: "bg-teal-500/10 text-teal-600 border-teal-500/20 dark:text-teal-400",
26	  Mid: "bg-amber-500/10 text-amber-600 border-amber-500/20 dark:text-amber-400",
27	  Low: "bg-orange-500/10 text-orange-600 border-orange-500/20 dark:text-orange-400",
28	  Gap: "bg-red-500/10 text-red-600 border-red-500/20 dark:text-red-400",
29	};
30	
31	const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
32	  const [showAll, setShowAll] = useState(false);
33	  const scores = r.category_scores_json;
34	
35	  const entries = scores && typeof scores === "object" && !Array.isArray(scores)
36	    ? Object.entries(scores as Record<string, any>).map(([skill, data]) => {
37	        const score = data && typeof data === "object" ? (data.score ?? 0) : (typeof data === "number" ? data : 0);
38	        const clamped = Math.max(0, Math.min(score, 100));
39	        return { skill, score: clamped, level: getSkillLevel(clamped) };
40	      }).sort((a, b) => b.score - a.score)
41	    : [];
42	
43	  const skillCount = entries.length;
44	  const overallScore = skillCount > 0
45	    ? Math.round(entries.reduce((sum, e) => sum + e.score, 0) / skillCount)
46	    : 0;
47	
48	  const topSkills = entries.filter((e) => e.score >= 40).slice(0, 5);
49	  const gapSkills = entries.filter((e) => e.score < 40);
50	
51	  return (
52	    <Card>
53	      <CardHeader className="pb-3 px-4 pt-4 flex-row items-center gap-2 space-y-0">
54	        <h4 className="text-sm font-medium text-foreground">Skills</h4>
55	        {skillCount > 0 && <Badge variant="secondary" className="text-[11px] h-5">{skillCount}</Badge>}
56	      </CardHeader>
57	      <CardContent className="px-4 pb-4 pt-0 space-y-4">
58	        {skillCount > 0 ? (
59	          <>
60	            {/* Score */}
61	            <div className="rounded-lg bg-foreground/[0.03] p-4 space-y-2">
62	              <div className="flex items-baseline gap-1.5">
63	                <span className="text-3xl font-bold tabular-nums text-foreground">{overallScore}</span>
64	                <span className="text-sm text-muted-foreground">/100</span>
65	                <span className="text-xs text-muted-foreground ml-2">
66	                  {entries.filter(e => e.score >= 70).length} strong · {entries.filter(e => e.score < 40).length} gaps
67	                </span>
68	              </div>
69	              <div className="h-2 rounded-full bg-secondary overflow-hidden">
70	                <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${overallScore}%` }} />
71	              </div>
72	            </div>
73	
74	            {/* Top skills — colored chips */}
75	            {topSkills.length > 0 && (
76	              <div className="flex flex-wrap gap-1.5">
77	                {topSkills.map((s) => (
78	                  <span key={s.skill} className={`text-xs font-medium px-2.5 py-1 rounded-full border ${levelChipCls[s.level]}`}>
79	                    {s.skill.replace(/_/g, " ")} · {s.level}
80	                  </span>
81	                ))}
82	              </div>
83	            )}
84	
85	            {/* Gaps */}
86	            {gapSkills.length > 0 && (
87	              <div className="space-y-1.5 pt-3 border-t border-border">
88	                <h5 className="text-xs text-muted-foreground font-medium">Gaps</h5>
89	                {gapSkills.map((s) => (
90	                  <div key={s.skill} className="flex items-center justify-between text-sm py-0.5">
91	                    <span className="text-muted-foreground capitalize">{s.skill.replace(/_/g, " ")}</span>
92	                    <span className={`text-[11px] font-medium px-2 py-0.5 rounded-full border ${levelChipCls[s.level]}`}>{s.level}</span>
93	                  </div>
94	                ))}
95	              </div>
96	            )}
97	
98	            {/* Expand */}
99	            {entries.length > 5 && (
100	              <button
101	                className="flex items-center justify-center gap-1 w-full text-xs text-muted-foreground hover:text-foreground transition-colors"
102	                onClick={() => setShowAll(!showAll)}
103	              >
104	                {showAll ? "Hide" : `View all ${skillCount}`}
105	                {showAll ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
106	              </button>
107	            )}
108	
109	            {showAll && (
110	              <div className="space-y-1 pt-2 border-t border-border">
111	                {entries.map((e) => (
112	                  <div key={e.skill} className="flex items-center justify-between text-sm py-0.5">
113	                    <span className="text-muted-foreground capitalize truncate">{e.skill.replace(/_/g, " ")}</span>
114	                    <span className={`text-[11px] font-medium px-2 py-0.5 rounded-full border shrink-0 ${levelChipCls[e.level]}`}>{e.level}</span>
115	                  </div>
116	                ))}
117	              </div>
118	            )}
119	          </>
120	        ) : (
121	          <p className="text-sm text-muted-foreground">No skill data</p>
122	        )}
123	      </CardContent>
124	    </Card>
125	  );
126	};
127	
128	export default SkillsDetailPanel;
