1	import { useState } from "react";
2	import { Card, CardContent, CardHeader } from "@/components/ui/card";
3	import { Badge } from "@/components/ui/badge";
4	import { ChevronDown, ChevronUp } from "lucide-react";
5	
6	interface Education {
7	  degree?: string;
8	  institution?: string;
9	  year?: string;
10	}
11	
12	interface EducationPanelProps {
13	  parsedJson: any;
14	  matchedMustHaves?: string[];
15	  missingMustHaves?: string[];
16	}
17	
18	const extractYear = (yearStr?: string | number): number | null => {
19	  if (yearStr == null) return null;
20	  if (typeof yearStr === "number") return yearStr >= 1900 && yearStr <= 2100 ? yearStr : null;
21	  const match = String(yearStr).match(/\b(19|20)\d{2}\b/g);
22	  if (!match) return null;
23	  return Math.max(...match.map(Number));
24	};
25	
26	type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";
27	
28	const inferLevel = (degree: string): EduLevel => {
29	  const d = degree.toLowerCase();
30	  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
31	  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
32	  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
33	  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
34	  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
35	  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd")) return "diploma";
36	  return "other";
37	};
38	
39	const LEVEL_LABEL: Record<EduLevel, string> = {
40	  doctorate: "PhD", masters: "Masters", bachelors: "Bachelors", diploma: "Diploma",
41	  higher_secondary: "12th", secondary: "10th", other: "Other",
42	};
43	
44	const isLowRelevance = (level: EduLevel): boolean => level === "secondary" || level === "higher_secondary";
45	
46	const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
47	  const [showAll, setShowAll] = useState(false);
48	  const education: Education[] = Array.isArray(parsedJson?.education) ? parsedJson.education : [];
49	  const certifications: string[] = Array.isArray(parsedJson?.certifications) ? parsedJson.certifications : [];
50	  const matchedLower = (Array.isArray(matchedMustHaves) ? matchedMustHaves : []).map((m) => String(m).toLowerCase());
51	  const missingLower = (Array.isArray(missingMustHaves) ? missingMustHaves : []).map((m) => String(m).toLowerCase());
52	
53	  const classified = education.map((edu) => {
54	    const degree = edu.degree || "";
55	    const institution = edu.institution || "";
56	    const combined = `${degree} ${institution}`.toLowerCase();
57	    const level = inferLevel(degree);
58	    const year = extractYear(edu.year);
59	    const isMatched = matchedLower.some((m) => m.split(/\s+/).filter((w) => w.length > 3).some((w) => combined.includes(w)));
60	    const isRelevant = !isLowRelevance(level);
61	    return { degree, institution, level, year, isMatched, isRelevant };
62	  });
63	
64	  // Education gaps
65	  const eduKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "mba"];
66	  const gaps = missingLower
67	    .filter((m) => eduKeywords.some((k) => m.includes(k)))
68	    .map((m) => (missingMustHaves || []).find((o) => o.toLowerCase() === m) || m);
69	
70	  return (
71	    <Card>
72	      <CardHeader className="pb-3 px-4 pt-4 flex-row items-center gap-2 space-y-0">
73	        <h4 className="text-sm font-medium text-foreground">Education</h4>
74	        <Badge variant="secondary" className="text-[11px] h-5">{classified.length}</Badge>
75	        {certifications.length > 0 && (
76	          <Badge variant="outline" className="text-[11px] h-5">{certifications.length} certs</Badge>
77	        )}
78	      </CardHeader>
79	      <CardContent className="px-4 pb-4 pt-0 space-y-4">
80	        {classified.length > 0 ? (
81	          <>
82	            <div className="space-y-3">
83	              {classified.slice(0, showAll ? undefined : 3).map((edu, i) => (
84	                <div key={i} className={`flex items-start gap-3 ${!edu.isRelevant ? "opacity-40" : ""}`}>
85	                  <div className={`mt-1.5 h-1.5 w-1.5 rounded-full shrink-0 ${edu.isMatched ? "bg-primary" : "bg-muted-foreground/40"}`} />
86	                  <div className="flex-1 min-w-0">
87	                    <div className="flex items-center gap-1.5 flex-wrap">
88	                      <span className="text-sm font-medium text-foreground">{edu.degree || "Degree"}</span>
89	                      <Badge variant="outline" className="text-[10px] h-4">{LEVEL_LABEL[edu.level]}</Badge>
90	                      {edu.isMatched && <Badge variant="secondary" className="text-[10px] h-4">JD Match</Badge>}
91	                    </div>
92	                    <p className="text-xs text-muted-foreground mt-0.5">
93	                      {edu.institution}{edu.institution && edu.year ? " · " : ""}{edu.year || ""}
94	                    </p>
95	                  </div>
96	                </div>
97	              ))}
98	            </div>
99	
100	            {classified.length > 3 && (
101	              <button
102	                className="flex items-center justify-center gap-1 w-full text-xs text-muted-foreground hover:text-foreground transition-colors"
103	                onClick={() => setShowAll(!showAll)}
104	              >
105	                {showAll ? "Show less" : `View all ${classified.length}`}
106	                {showAll ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
107	              </button>
108	            )}
109	          </>
110	        ) : (
111	          <p className="text-sm text-muted-foreground">No education data</p>
112	        )}
113	
114	        {/* Gaps */}
115	        {gaps.length > 0 && (
116	          <div className="space-y-2 pt-3 border-t border-border">
117	            <h5 className="text-xs text-muted-foreground font-medium">Gaps</h5>
118	            {gaps.map((gap, i) => (
119	              <div key={i} className="flex items-center gap-2 text-sm">
120	                <span className="mt-0.5 h-1.5 w-1.5 rounded-full bg-red-500 shrink-0" />
121	                <span className="text-muted-foreground">{gap}</span>
122	              </div>
123	            ))}
124	          </div>
125	        )}
126	
127	        {/* Certifications */}
128	        {certifications.length > 0 && (
129	          <div className="space-y-2 pt-3 border-t border-border">
130	            <h5 className="text-xs text-muted-foreground font-medium">Certifications</h5>
131	            <div className="flex flex-wrap gap-1.5">
132	              {certifications.map((cert, i) => (
133	                <Badge key={i} variant="outline" className="text-xs">{cert}</Badge>
134	              ))}
135	            </div>
136	          </div>
137	        )}
138	      </CardContent>
139	    </Card>
140	  );
141	};
142	
143	export default EducationPanel;
