14	interface AddToPoolButtonProps {
15	  resumeId: string;
16	  jobId: string;
17	  teamId: string;
18	  isInPool?: boolean;
19	  onPoolChange?: (inPool: boolean) => void;
20	  size?: "sm" | "default";
21	  variant?: "ghost" | "outline" | "default";
22	}
23	
24	const AddToPoolButton = ({
25	  resumeId,
26	  jobId,
27	  teamId,
28	  isInPool = false,
29	  onPoolChange,
30	  size = "sm",
31	  variant = "outline",
32	}: AddToPoolButtonProps) => {
33	  const { user } = useAuth();
34	  const [inPool, setInPool] = useState(isInPool);
35	  const [loading, setLoading] = useState(false);
36	
37	  const handleToggle = async () => {
38	    if (!user) {
39	      toast.error("You must be logged in");
40	      return;
41	    }
42	
43	    setLoading(true);
44	    try {
45	      if (inPool) {
46	        // Remove from pool
47	        const { error } = await (supabase as any)
48	          .from("talent_pool")
49	          .delete()
50	          .eq("resume_id", resumeId)
51	          .eq("team_id", teamId);
52	
53	        if (error) throw error;
54	        setInPool(false);
55	        onPoolChange?.(false);
56	        toast.success("Removed from talent pool");
57	      } else {
58	        // Add to pool
59	        const { error } = await (supabase as any)
60	          .from("talent_pool")
61	          .insert({
62	            resume_id: resumeId,
63	            original_job_id: jobId,
64	            team_id: teamId,
65	            added_by: user.id,
66	          });
67	
68	        if (error) {
69	          if (error.code === "23505") {
70	            // Already in pool (unique constraint)
71	            setInPool(true);
72	            onPoolChange?.(true);
73	            toast.info("Already in talent pool");
74	            return;
75	          }
76	          throw error;
77	        }
78	        setInPool(true);
79	        onPoolChange?.(true);
80	        toast.success("Added to talent pool");
81	      }
82	    } catch (err: unknown) {
83	      const msg = err instanceof Error ? err.message : "Failed to update talent pool";
84	      toast.error(msg);
85	    } finally {
86	      setLoading(false);
87	    }
88	  };
89	
90	  return (
91	    <TooltipProvider delayDuration={300}>
92	      <Tooltip>
93	        <TooltipTrigger asChild>
94	          <Button
95	            variant={inPool ? "default" : variant}
96	            size={size}
97	            className={`h-8 gap-1.5 text-xs ${inPool ? "bg-primary/90" : ""}`}
98	            onClick={handleToggle}
99	            disabled={loading}
100	          >
101	            {loading ? (
102	              <Loader2 className="h-3.5 w-3.5 animate-spin" />
103	            ) : inPool ? (
104	              <BookmarkCheck className="h-3.5 w-3.5" />
105	            ) : (
106	              <Bookmark className="h-3.5 w-3.5" />
107	            )}
108	            {inPool ? "In Pool" : "Save to Pool"}
109	          </Button>
110	        </TooltipTrigger>
111	        <TooltipContent>
112	          {inPool ? "Remove from talent pool" : "Save to talent pool for future roles"}
113	        </TooltipContent>
114	      </Tooltip>
115	    </TooltipProvider>
116	  );
117	};
